// Embeds the 1Password SDK's WASM core in the compiled binary. @1password/sdk-core reads
// `core_bg.wasm` from disk at runtime (a path built from __dirname), which Bun cannot see, so a
// plain `bun build --compile` bakes in the build machine's node_modules path and the binary breaks
// anywhere else (the distroless image). This plugin aliases the package to a shim whose only
// change is `require("<absolute path>/core_bg.wasm")`; Bun's file loader then embeds the bytes.
//
// The shim is generated by a string replace and the build FAILS LOUDLY unless both hold:
//  - the target line exists in the installed core.js (an SDK bump that moved it is caught), and
//  - the sha256 of core_bg.wasm is the pinned version's (a different binary is never embedded).
// Bumping @1password/sdk-core means updating SDK_CORE_VERSION and CORE_WASM_SHA256 here on purpose.
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import type { BunPlugin } from "bun";

export const SDK_CORE_VERSION = "0.5.0";
export const CORE_WASM_SHA256 = "97aa9140c5c923b39b41c059d5ab98e214b5fc78a80203d0026708cfbce8d6ab";
/** The exact line in core.js that reads the WASM from disk. */
export const TARGET_LINE = `const path = require('path').join(__dirname, 'core_bg.wasm');`;

export interface CoreFiles {
  version: string;
  coreJs: string;
  wasm: Uint8Array;
  /** Absolute path of core_bg.wasm, for the require in the shim. */
  wasmPath: string;
}

/** Reads the installed @1password/sdk-core, resolved from `fromDir` (the core package). */
export function readInstalledCore(fromDir: string): CoreFiles {
  const main = Bun.resolveSync("@1password/sdk-core", fromDir);
  const dir = dirname(main);
  const pkgPath = join(dir, "..", "package.json");
  const version = (JSON.parse(readFileSync(pkgPath, "utf8")) as { version: string }).version;
  const wasmPath = join(dir, "core_bg.wasm");
  return { version, coreJs: readFileSync(main, "utf8"), wasm: readFileSync(wasmPath), wasmPath };
}

/** The shim's source. Throws unless the version, the target line and the WASM hash all match. */
export function buildShim(
  core: CoreFiles,
  pinned: { version: string; sha256: string } = {
    version: SDK_CORE_VERSION,
    sha256: CORE_WASM_SHA256,
  },
): string {
  if (core.version !== pinned.version) {
    throw new Error(
      `@1password/sdk-core is ${core.version}, the embed shim is pinned to ${pinned.version}: update scripts/op-embed.ts on purpose`,
    );
  }
  const sha = createHash("sha256").update(core.wasm).digest("hex");
  if (sha !== pinned.sha256) {
    throw new Error(
      `core_bg.wasm sha256 is ${sha}, expected ${pinned.sha256}: refusing to embed an unreviewed binary`,
    );
  }
  const n = core.coreJs.split(TARGET_LINE).length - 1;
  if (n !== 1) {
    throw new Error(
      `expected exactly one WASM read line in @1password/sdk-core core.js, found ${n}: the SDK changed, review the embed shim`,
    );
  }
  return core.coreJs.replace(
    TARGET_LINE,
    `const path = require(${JSON.stringify(core.wasmPath)});`,
  );
}

/** A Bun.build plugin that aliases `@1password/sdk-core` to the embedding shim. */
export function onePasswordEmbedPlugin(fromDir: string): BunPlugin {
  return {
    name: "embed-1password-core",
    setup(build) {
      const shim = buildShim(readInstalledCore(fromDir));
      const dir = mkdtempSync(join(tmpdir(), "op-embed-"));
      const file = join(dir, "core-shim.cjs");
      writeFileSync(file, shim);
      build.onResolve({ filter: /^@1password\/sdk-core$/ }, () => ({ path: file }));
    },
  };
}
